#!/usr/bin/env bun
// Generates the native design tokens from apps/design/tokens.json.
//   bun apps/tools/design-tokens.mjs          write NoahTokens.swift and NoahTokens.kt
//   bun apps/tools/design-tokens.mjs --check  fail if the generated files are stale
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const tokens = JSON.parse(readFileSync(join(root, "apps/design/tokens.json"), "utf8"));
const swiftPath = join(root, "apps/ios/Noah/DesignSystem/NoahTokens.swift");
const kotlinPath = join(root, "apps/android/app/src/main/java/com/noahwallet/ui/design/NoahTokens.kt");
const header = "Generated by apps/tools/design-tokens.mjs from apps/design/tokens.json. Do not edit.";

/** "#RRGGBB" or "#RRGGBBAA" → { rgb, alpha } */
function parseColor(hex) {
  const m = /^#([0-9A-Fa-f]{6})([0-9A-Fa-f]{2})?$/.exec(hex);
  if (!m) throw new Error(`Bad colour ${hex}`);
  return { rgb: m[1].toUpperCase(), alpha: m[2] ? m[2].toUpperCase() : "FF" };
}
const num = (n) => (Number.isInteger(n) ? `${n}` : `${+n.toFixed(4)}`);
const float = (n) => `${+n.toFixed(4)}f`;
const stiffness = (response) => (2 * Math.PI / response) ** 2;

const uiTextStyle = {
  wordmark: "largeTitle", balance: "largeTitle", amount: "title1", code: "title2", title: "title1",
  sheetTitle: "title2", field: "title2", handle: "title1", body: "body", button: "headline",
  sub: "subheadline", caption: "caption1",
};

function swift() {
  const c = tokens.color, t = tokens.type, m = tokens.motion, f = tokens.font.display;
  const lines = [];
  const p = (s = "") => lines.push(s);
  p(`// ${header}`);
  p("import SwiftUI");
  p("import UIKit");
  p("");
  p("/// Redesign tokens.");
  p("enum NoahTokens {");
  p("    enum Colors {");
  for (const [name, v] of Object.entries(c)) {
    const l = parseColor(v.light), d = parseColor(v.dark);
    p(`        static let ${name} = dynamic(light: 0x${l.rgb}${l.alpha}, dark: 0x${d.rgb}${d.alpha})`);
  }
  p("");
  p("        /// 0xRRGGBBAA for light and dark appearance.");
  p("        private static func dynamic(light: UInt32, dark: UInt32) -> Color {");
  p("            Color(uiColor: UIColor { $0.userInterfaceStyle == .dark ? rgba(dark) : rgba(light) })");
  p("        }");
  p("        private static func rgba(_ v: UInt32) -> UIColor {");
  p("            UIColor(red: CGFloat((v >> 24) & 0xFF) / 255, green: CGFloat((v >> 16) & 0xFF) / 255,");
  p("                    blue: CGFloat((v >> 8) & 0xFF) / 255, alpha: CGFloat(v & 0xFF) / 255)");
  p("        }");
  p("    }");
  p("");
  for (const [group, key] of [["Space", "space"], ["Radius", "radius"], ["Size", "size"]]) {
    p(`    enum ${group} {`);
    for (const [name, v] of Object.entries(tokens[key])) p(`        static let ${name}: CGFloat = ${num(v)}`);
    p("    }");
    p("");
  }
  p("    enum Motion {");
  for (const [name, v] of Object.entries(m)) {
    if (typeof v !== "object" || name.startsWith("$")) continue;
    p(`        /// ${v.use}`);
    p(`        static let ${name} = Animation.spring(response: ${num(v.response)}, dampingFraction: ${num(v.damping)})`);
  }
  p(`        /// Reduce Motion replaces travel, scale and flips with this cross-fade.`);
  p(`        static let reduceMotionFade = Animation.easeInOut(duration: ${num(m.reduceMotionFadeMs / 1000)})`);
  p("    }");
  p("");
  p("    struct TextStyle: Sendable {");
  p("        let size: CGFloat");
  p("        let lineHeight: CGFloat?");
  p("        let weight: Font.Weight");
  p("        let display: Bool");
  p("        /// Tracking in em, multiplied by the scaled size.");
  p("        let tracking: CGFloat");
  p("        let textStyle: UIFont.TextStyle");
  p("");
  p(`        private var displayName: String { weight == .semibold ? "${f.ios.semibold}" : "${f.ios.medium}" }`);
  p("");
  p("        func font(size: CGFloat) -> Font {");
  p(`            guard display else { return .system(size: size, weight: weight) }`);
  p("            return .custom(displayName, fixedSize: size)");
  p("        }");
  p("");
  p("        /// The UIKit font behind `font(size:)`, for its real line height.");
  p("        func uiFont(size: CGFloat) -> UIFont {");
  p("            let uiWeight: UIFont.Weight = weight == .semibold ? .semibold : weight == .medium ? .medium : .regular");
  p("            guard display, let font = UIFont(name: displayName, size: size) else { return .systemFont(ofSize: size, weight: uiWeight) }");
  p("            return font");
  p("        }");
  p("    }");
  p("");
  p("    enum Typography {");
  for (const [name, v] of Object.entries(t)) {
    const weight = { regular: ".regular", medium: ".medium", semibold: ".semibold" }[v.weight];
    p(`        static let ${name} = TextStyle(size: ${num(v.size)}, lineHeight: ${v.lineHeight ? num(v.lineHeight) : "nil"}, weight: ${weight}, display: ${v.font === "display"}, tracking: ${num(v.tracking)}, textStyle: .${uiTextStyle[name] ?? "body"})`);
  }
  p("    }");
  p("}");
  p("");
  p("/// Applies a token text style, scaled with Dynamic Type.");
  p("struct NoahTextModifier: ViewModifier {");
  p("    let style: NoahTokens.TextStyle");
  p("    @Environment(\\.dynamicTypeSize) private var dynamicTypeSize");
  p("");
  p("    @ViewBuilder func body(content: Content) -> some View {");
  p("        let traits = UITraitCollection(preferredContentSizeCategory: UIContentSizeCategory(dynamicTypeSize))");
  p("        let metrics = UIFontMetrics(forTextStyle: style.textStyle)");
  p("        let size = metrics.scaledValue(for: style.size, compatibleWith: traits)");
  p("        let lineHeight = style.lineHeight.map { metrics.scaledValue(for: $0, compatibleWith: traits) }");
  p("        let styled = content.font(style.font(size: size)).tracking(style.tracking * size)");
  p("        if #available(iOS 26.0, *) {");
  p("            styled.lineHeight(lineHeight.map { .exact(points: $0) })");
  p("        } else {");
  p("            // No line-box API before iOS 26: space lines apart, and single lines keep the font's own height.");
  p("            styled.lineSpacing(lineHeight.map { max(0, $0 - style.uiFont(size: size).lineHeight) } ?? 0)");
  p("        }");
  p("    }");
  p("}");
  p("");
  p("extension View {");
  p("    func noahText(_ style: NoahTokens.TextStyle) -> some View { modifier(NoahTextModifier(style: style)) }");
  p("}");
  return lines.join("\n") + "\n";
}

function kotlin() {
  const c = tokens.color, t = tokens.type, m = tokens.motion, f = tokens.font.display;
  const lines = [];
  const p = (s = "") => lines.push(s);
  const camel = (s) => s;
  p(`// ${header}`);
  p("package com.noahwallet.ui.design");
  p("");
  p("import androidx.compose.animation.core.SpringSpec");
  p("import androidx.compose.animation.core.spring");
  p("import androidx.compose.ui.graphics.Color");
  p("import androidx.compose.ui.text.TextStyle");
  p("import androidx.compose.ui.text.font.Font");
  p("import androidx.compose.ui.text.font.FontFamily");
  p("import androidx.compose.ui.text.font.FontWeight");
  p("import androidx.compose.ui.unit.dp");
  p("import androidx.compose.ui.unit.em");
  p("import androidx.compose.ui.unit.sp");
  p("import com.noahwallet.R");
  p("");
  p("/** Redesign tokens. */");
  p("object NoahTokens {");
  p("    class Palette(");
  for (const name of Object.keys(c)) p(`        val ${camel(name)}: Color,`);
  p("    )");
  for (const mode of ["light", "dark"]) {
    p("");
    p(`    val ${mode === "light" ? "Light" : "Dark"} = Palette(`);
    for (const [name, v] of Object.entries(c)) {
      const col = parseColor(v[mode]);
      p(`        ${camel(name)} = Color(0x${col.alpha}${col.rgb}),`);
    }
    p("    )");
  }
  p("");
  for (const [group, key] of [["Space", "space"], ["Radius", "radius"], ["Size", "size"]]) {
    p(`    object ${group} {`);
    for (const [name, v] of Object.entries(tokens[key])) p(`        val ${name} = ${num(v)}.dp`);
    p("    }");
    p("");
  }
  p("    /** SwiftUI response/dampingFraction mapped to Compose: stiffness = (2π/response)². */");
  p("    object Motion {");
  for (const [name, v] of Object.entries(m)) {
    if (typeof v !== "object" || name.startsWith("$")) continue;
    p(`        /** ${v.use} */`);
    p(`        fun <T> ${name}(): SpringSpec<T> = spring(dampingRatio = ${float(v.damping)}, stiffness = ${float(stiffness(v.response))})`);
  }
  p(`        const val REDUCE_MOTION_FADE_MS = ${m.reduceMotionFadeMs}`);
  p("    }");
  p("");
  p(`    val Display = FontFamily(Font(R.font.${f.android.medium}, FontWeight.Medium), Font(R.font.${f.android.semibold}, FontWeight.SemiBold))`);
  p("");
  p("    object Typography {");
  for (const [name, v] of Object.entries(t)) {
    const weight = { regular: "FontWeight.Normal", medium: "FontWeight.Medium", semibold: "FontWeight.SemiBold" }[v.weight];
    const parts = [
      v.font === "display" ? "fontFamily = Display" : null,
      `fontWeight = ${weight}`,
      `fontSize = ${num(v.size)}.sp`,
      v.lineHeight ? `lineHeight = ${num(v.lineHeight)}.sp` : null,
      v.tracking ? `letterSpacing = (${num(v.tracking)}).em` : null,
    ].filter(Boolean);
    p(`        val ${name} = TextStyle(${parts.join(", ")})`);
  }
  p("    }");
  p("}");
  return lines.join("\n") + "\n";
}

const outputs = [[swiftPath, swift()], [kotlinPath, kotlin()]];
if (process.argv.includes("--check")) {
  const stale = outputs.filter(([path, text]) => !existsSync(path) || readFileSync(path, "utf8") !== text);
  if (stale.length) {
    console.error(`Stale design tokens: ${stale.map(([p]) => p).join(", ")}. Run bun apps/tools/design-tokens.mjs`);
    process.exit(1);
  }
} else {
  for (const [path, text] of outputs) writeFileSync(path, text);
  console.log(`Wrote ${outputs.map(([p]) => p.replace(root + "/", "")).join(" and ")}`);
}
